// Build a function that fetches data from three different "APIs" (simulated with `setTimeout` and random success/failure). Use `Promise.allSettled` to g...

solution_code:
// Callback pattern (avoid — callback hell)
function fetchUserCallback(id, callback) {
  setTimeout(() => {
    callback({ id, name: "Alice" });
  }, 1000);
}

// Promise pattern
function fetchUser(id) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (id > 0) {
        resolve({ id, name: "Alice" });
      } else {
        reject(new Error("Invalid ID"));
      }
    }, 1000);
  });
}

// Promise chaining
fetchUser(1)
  .then(user => fetchPosts(user.id))
  .then(posts => console.log(posts))
  .catch(err => console.error(err))
  .finally(() => console.log("Done"));

// Async/await (preferred)
async function getUserData(id) {
  try {
    const user = await fetchUser(id);
    const posts = await fetchPosts(user.id);
    return { user, posts };
  } catch (error) {
    console.error("Failed:", error.message);
    throw error;
  }
}

// Parallel execution
async function getMultipleUsers(ids) {
  const promises = ids.map(id => fetchUser(id));
  return Promise.all(promises);  // Waits for all
}

// Promise.allSettled — waits for all, never rejects
const results = await Promise.allSettled([fetchUser(1), fetchUser(-1)]);
// results[0]: { status: 'fulfilled', value: {...} }
// results[1]: { status: 'rejected', reason: Error }

// Promise.race — first to settle wins
const fastest = await Promise.race([fetchUser(1), fetchUser(2)]);
